def grade(case, model_output):
    out = parse_json(model_output)      # None if not valid JSON
    if out is None:
        return Fail("invalid JSON")
    if out["decision"] not in {"approve", "deny", "escalate"}:
        return Fail(f"bad decision: {out['decision']}")
    if not (0 <= out["amount"] <= case["max_refund"]):
        return Fail("amount out of policy range")
    return Pass()

def run_eval(cases, run_model):
    results = [grade(c, run_model(c["input"])) for c in cases]
    passed = sum(r.ok for r in results)
    return passed / len(cases), results   # score + per-case detail

